-- ============================================================
-- TRANSLATION RULES SEED — from production (192.95.36.154)
-- Loads ALL translation rules (SMPP/HTTP/VoiceOTP SID, number,
-- content, OTP extract, blacklist/whitelist). Regenerate via:
--   pg_dump -h localhost -U sms_user -d sms_platform --data-only --column-inserts -t translations
-- ============================================================
TRUNCATE translations RESTART IDENTITY;



-- Re-sync the id sequence so NEW rules created after seeding get higher ids
-- than the seeded ones (rules sort by priority ASC, id DESC -- newer rules win
-- within the same priority).
SELECT setval('translations_id_seq', (SELECT COALESCE(MAX(id), 1) FROM translations));
